// Dynamically converts merged categories to exact child category names based on article context
export const sanitizeDisplayCategory = (category: string, title = ""): string => {
  if (!category) return "";
  const t = title || "";
  if (category === "사회/정치") {
    // Check keywords in title to decide if Politics or Social
    const isPolitics = /토론|원전|공약|지선|선거|정치|정권|대선|여론|핵심|국무|정당|의원|국회|부처|기자회견/i.test(t);
    return isPolitics ? "정치" : "사회";
  }
  if (category === "경제/문화") {
    // Check keywords in title to decide if Culture or Economy
    const isCulture = /문화|비건|라이프|동물권|예술|음악|공연|축제|도서|문학|전시/i.test(t);
    return isCulture ? "문화" : "경제";
  }
  if (category === "복지/미래비전") {
    // Check keywords in title to decide if Future Vision or Welfare
    const isFuture = /미래|비전|첨단|인공지능|AI|우주|기술|성장/i.test(t);
    return isFuture ? "미래비전" : "복지";
  }
  return category;
};

