                          return (
                            <div
                              key={f}
                              className={cn("h-full transition-all duration-500", colors[i].split(" ")[0])}
                              style={{ width: `${pct}%` }}
                              title={`${f}: ${counts[i]}명 (${Math.round(pct)}%)`}
                            />
                          );
