  const getWorkshopSubType = (item: any) => {
    let sub = item.subCategory;
    if (sub === "⚡ 독창적 브랜드 IP" || sub === "독창적 브랜드 IP" || sub === "캐릭터 IP") {
      sub = "⚡ 캐릭터 IP";
    }
    if (sub) {
      return sub;
    }
    let subType = "⚡ 캐릭터 IP";
    const t = item.title.toLowerCase();
    const c = item.content?.toLowerCase() || "";
    if (t.includes("시집") || t.includes("시 ") || c.includes("시집") || t.includes("poetry")) subType = "📝 시집";
    else if (t.includes("동화") || c.includes("동화") || t.includes("어린이") || t.includes("아이")) subType = "🧸 동화책";
    else if (t.includes("웹툰") || t.includes("만화") || c.includes("웹툰") || t.includes("comic")) subType = "🎬 웹툰";
    else if (t.includes("카드") || t.includes("뉴스") || c.includes("카드뉴스") || t.includes("infographic")) subType = "📊 카드뉴스";
    else if (t.includes("캐릭터") || t.includes("일러스트") || c.includes("캐릭터") || t.includes("character") || t.includes("브랜드") || t.includes("ip") || c.includes("브랜드") || c.includes("ip")) subType = "⚡ 캐릭터 IP";
    return subType;
  };

  const getCleanSubTypeName = (subType: string) => {
    if (subType === "📝 시집") return "감성 시집";
    return subType.replace(/[^\w\sㄱ-ㅎㅏ-ㅣ가-힣]/g, "").trim();
  };

  const highlightMatch = (text: string, queryText: string) => {
    if (!queryText || !queryText.trim()) return text;
    try {
      const escapedQuery = queryText.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
      const parts = text.split(new RegExp(`(${escapedQuery})`, 'gi'));
      return (
        <>
          {parts.map((part, index) => 
            part.toLowerCase() === queryText.toLowerCase() ? (
              <mark key={index} className="bg-yellow-100 dark:bg-yellow-950/80 text-yellow-900 dark:text-yellow-200 px-0.5 rounded font-black border-b-2 border-yellow-400 dark:border-yellow-600 transition-all">
                {part}
              </mark>
            ) : (
              part
            )
          )}
        </>
      );
    } catch (e) {
      return text;
    }
  };

