const renderFormattedContent = (text: string) => {
  if (!text) return null;
  const lines = text.split("\n");
  return lines.map((line, idx) => {
    let currentLine = line;
    let isHeading = false;
    let isQuote = false;
    let isBullet = false;

    if (currentLine.startsWith("## ")) {
      isHeading = true;
      currentLine = currentLine.substring(3);
    } else if (currentLine.startsWith("> ")) {
      isQuote = true;
      currentLine = currentLine.substring(2);
    } else if (currentLine.startsWith("- ")) {
      isBullet = true;
      currentLine = currentLine.substring(2);
    }

    const parseInLines = (txt: string) => {
      const parts: React.ReactNode[] = [];
      let lastIndex = 0;
      const regex = /(\*\*.*?\*\*|<mark>.*?<\/mark>)/g;
      let match;
      while ((match = regex.exec(txt)) !== null) {
        if (match.index > lastIndex) {
          parts.push(txt.substring(lastIndex, match.index));
        }
        const token = match[0];
        if (token.startsWith("**") && token.endsWith("**")) {
          const content = token.substring(2, token.length - 2);
          parts.push(
            <strong key={match.index} className="font-extrabold text-zinc-950 dark:text-white bg-amber-500/10 px-0.5 rounded">
              {content}
            </strong>
          );
        } else if (token.startsWith("<mark>") && token.endsWith("</mark>")) {
          const content = token.substring(6, token.length - 7);
          parts.push(
            <mark key={match.index} className="bg-amber-300 dark:bg-amber-500/30 text-zinc-900 dark:text-zinc-100 px-1 py-0.5 rounded font-bold">
              {content}
            </mark>
          );
        }
        lastIndex = regex.lastIndex;
      }
      if (lastIndex < txt.length) {
        parts.push(txt.substring(lastIndex));
      }
      return parts.length > 0 ? parts : txt;
    };

    if (isHeading) {
      return (
        <h2 key={idx} className="text-lg font-black text-orange-600 dark:text-orange-500 mt-5 mb-2.5 tracking-tight border-b border-zinc-100 dark:border-zinc-800 pb-1">
          {parseInLines(currentLine)}
        </h2>
      );
    }
    if (isQuote) {
      return (
        <blockquote key={idx} className="pl-3.5 border-l-4 border-amber-500 my-3 text-zinc-650 dark:text-zinc-350 italic bg-amber-500/[0.02] p-2.5 rounded-r-xl">
          {parseInLines(currentLine)}
        </blockquote>
      );
    }
    if (isBullet) {
      return (
        <li key={idx} className="list-disc list-inside ml-1.5 text-zinc-800 dark:text-zinc-200 py-0.5">
          {parseInLines(currentLine)}
        </li>
      );
    }

    return (
      <p key={idx} className="min-h-[1.5rem] my-1.5 leading-relaxed text-zinc-850 dark:text-zinc-200">
        {parseInLines(currentLine)}
      </p>
    );
  });
};

