const getCategoryFallbackImage = (category: string = "일반기사", title: string = "", id: string = ""): string => {
  let hash = 0;
  const combined = (title || "") + (id || "") + (category || "");
  for (let i = 0; i < combined.length; i++) {
    hash = combined.charCodeAt(i) + ((hash << 5) - hash);
  }
  const idx = Math.abs(hash);

  const techPool = [
    "https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1620712943543-bcc4688e7485?auto=format&fit=crop&q=80&w=800"
  ];

  const politicsPool = [
    "https://images.unsplash.com/photo-1540910419892-4a36d2c3266c?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1529107386315-e1a2ed48a620?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1450133064473-71024230f91b?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1541872703-74c5e44368f9?auto=format&fit=crop&q=80&w=800"
  ];

  const ecoPool = [
    "https://images.unsplash.com/photo-1506157786151-b8491531f063?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1526304640581-d334cdbbf45e?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&q=80&w=800"
  ];

  const societyPool = [
    "https://images.unsplash.com/photo-1517457373958-b7bdd4587205?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1491438590914-bc09fcaaf77a?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1516594798947-e65505dbb29d?auto=format&fit=crop&q=80&w=800"
  ];

  const videoTVPool = [
    "https://images.unsplash.com/photo-1533929736458-ca588d08c8be?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1492691527719-9d1e07e534b4?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1485827404703-89b55fcc595e?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1478720568477-152d9b164e26?auto=format&fit=crop&q=80&w=800"
  ];

  const defaultPool = [
    "https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1495446815901-a7297e633e8d?auto=format&fit=crop&q=80&w=800",
    "https://images.unsplash.com/photo-1504711311083-8587847ecc2d?auto=format&fit=crop&q=80&w=800"
  ];

  const catStr = category || "일반기사";
  if (catStr === "이솔나라TV" || catStr === "온에어") {
    return videoTVPool[idx % videoTVPool.length];
  }
  if (catStr.includes("정치") || catStr.includes("사회")) {
    const combinedPool = [...politicsPool, ...societyPool];
    return combinedPool[idx % combinedPool.length];
  }
  if (catStr.includes("경제")) {
    return ecoPool[idx % ecoPool.length];
  }
  if (catStr.includes("미래") || catStr.includes("AI") || catStr.includes("IT") || catStr.includes("스타") || catStr.includes("포토")) {
    return techPool[idx % techPool.length];
  }

  const allImages = [...defaultPool, ...societyPool, ...ecoPool, ...techPool, ...videoTVPool];
  return allImages[idx % allImages.length];
};

const translateText = (text: string, to: "KOR" | "ENG" | "JPN"): string => {
  if (to === "KOR") return text;
  
  if (to === "ENG") {
    let translated = text
      .replace(/대통령/g, "President")
      .replace(/기자/g, "Reporter")
      .replace(/한국/g, "Korea")
      .replace(/정부/g, "Government")
      .replace(/AI/gi, "Artificial Intelligence")
      .replace(/이솔포스트/g, "ISOL POST")
      .replace(/시민/g, "Citizen")
      .replace(/사회/g, "Society")
      .replace(/경제/g, "Economy")
      .replace(/정치/g, "Politics")
      .replace(/복지/g, "Welfare")
      .replace(/미래/g, "Future")
      .replace(/돌봄/g, "Care Coordination")
      .replace(/로봇/g, "Robotics Intelligence")
      .replace(/보도/g, "Exclusive Report");
    
    _TRANSLATIONS_ENG.forEach((pair) => {
      if (text.includes(pair.from)) {
        translated = translated.replace(new RegExp(pair.from, "gi"), pair.to);
      }
    });

    if (translated === text) {
      return "[Machine Translated] " + text.replace(/습니다/g, "s.").replace(/이다/g, " is").replace(/입니다/g, " of ISOL POST.");
    }
    return translated;
  }

  if (to === "JPN") {
    let translated = text
      .replace(/대통령/g, "大統領")
      .replace(/기자/g, "記者")
      .replace(/한국/g, "韓国")
      .replace(/정부/g, "政府")
      .replace(/이솔포스트/g, "イソルポスト")
      .replace(/시민/g, "市民")
      .replace(/사회/g, "社会")
      .replace(/경제/g, "経済")
      .replace(/정치/g, "政治")
      .replace(/복지/g, "福祉")
      .replace(/미래/g, "未来")
      .replace(/돌봄/g, "ケアシステム")
      .replace(/로봇/g, "ロボット")
      .replace(/보도/g, "独占報道");

    _TRANSLATIONS_JPN.forEach((pair) => {
      if (text.includes(pair.from)) {
        translated = translated.replace(new RegExp(pair.from, "gi"), pair.to);
      }
    });

    if (translated === text) {
      return "[自動翻訳] " + text + "。以上の記事はイソルポスト自動翻訳システムによって翻訳されました。";
    }
    return translated;
  }

  return text;
};

