  const [ragTopK, setRagTopK] = React.useState<number>(3);
  const [ragDocuments, setRagDocuments] = React.useState<RagDocument[]>([]);

  const loadRagDocs = React.useCallback(async () => {
    try {
      const docsList = await getRagDocumentsFromDB();
      if (docsList && docsList.length > 0) {
        setRagDocuments(docsList);
        localStorage.setItem("isol_rag_documents_v1", JSON.stringify(docsList));
      } else {
        const local = localStorage.getItem("isol_rag_documents_v1");
        if (local) {
          setRagDocuments(JSON.parse(local));
        } else {
          const seeded = await seedSampleRagDocumentsInDB(ragChunkSize, ragChunkOverlap);
          setRagDocuments(seeded);
          localStorage.setItem("isol_rag_documents_v1", JSON.stringify(seeded));
        }
      }
    } catch (e) {
      console.warn("Firestore RAG load failed, using local storage fallback:", e);
      const local = localStorage.getItem("isol_rag_documents_v1");
      if (local) {
        setRagDocuments(JSON.parse(local));
      } else {
        try {
          const seeded = await seedSampleRagDocumentsInDB(ragChunkSize, ragChunkOverlap);
          setRagDocuments(seeded);
          localStorage.setItem("isol_rag_documents_v1", JSON.stringify(seeded));
        } catch (err) {
          console.error("Local fallback seed failed", err);
        }
      }
    }
  }, [ragChunkSize, ragChunkOverlap]);

  React.useEffect(() => {
    loadRagDocs();
  }, [loadRagDocs]);

  // Mobile specific settings: Reader Font Size, Eye-care overlay
  const [readerFontSize, setReaderFontSize] = React.useState<"sm" | "base" | "lg" | "xl">("base");
